return {api_version=1,id="CS1_129",name="Inner Fire",text="Change a minion's Attack to be equal to its Health.",set="EXPERT1",type="spell",class="priest",rarity="common",cost=1,target_mode="required",targets=function(ctx)return ctx:minions()end,on_play=function(ctx,self,target)cardlib.effects.modify(ctx, target,{stat="attack",operation="set",value=ctx:entity(target).health})end}
